import { cn, Slot } from '@cascivo/core/pure'
import type { HTMLAttributes } from 'react'
import styles from './item.module.css'

export interface ItemProps extends HTMLAttributes<HTMLDivElement> {
  /**
   * When true, renders the child element as the root via Slot, merging props (polymorphic
   * rendering).
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  asChild?: boolean
  /**
   * `muted` gives the row a subtle background — for a selected or highlighted item;
   * `default` leaves it transparent.
   *
   * @defaultValue `default`
   * @see the component manifest
   */
  variant?: 'default' | 'muted'
  size?: 'sm' | 'md'
}

export function Item({
  asChild = false,
  variant = 'default',
  size = 'md',
  className,
  children,
  ...props
}: ItemProps) {
  const Comp = asChild ? Slot : 'div'
  return (
    <Comp
      data-variant={variant}
      data-size={size}
      className={cn(styles['item'], className as string | undefined)}
      {...(props as Record<string, unknown>)}
    >
      {children}
    </Comp>
  )
}

export interface ItemMediaProps extends HTMLAttributes<HTMLDivElement> {}

export function ItemMedia({ className, children, ...props }: ItemMediaProps) {
  return (
    <div className={cn(styles['media'], className as string | undefined)} {...props}>
      {children}
    </div>
  )
}

export interface ItemContentProps extends HTMLAttributes<HTMLDivElement> {}

export function ItemContent({ className, children, ...props }: ItemContentProps) {
  return (
    <div className={cn(styles['content'], className as string | undefined)} {...props}>
      {children}
    </div>
  )
}

export interface ItemTitleProps extends HTMLAttributes<HTMLDivElement> {}

export function ItemTitle({ className, children, ...props }: ItemTitleProps) {
  return (
    <div className={cn(styles['title'], className as string | undefined)} {...props}>
      {children}
    </div>
  )
}

export interface ItemDescriptionProps extends HTMLAttributes<HTMLParagraphElement> {}

export function ItemDescription({ className, children, ...props }: ItemDescriptionProps) {
  return (
    <p className={cn(styles['description'], className as string | undefined)} {...props}>
      {children}
    </p>
  )
}

export interface ItemActionsProps extends HTMLAttributes<HTMLDivElement> {}

export function ItemActions({ className, children, ...props }: ItemActionsProps) {
  return (
    <div className={cn(styles['actions'], className as string | undefined)} {...props}>
      {children}
    </div>
  )
}

@layer cascivo.component {
  .item {
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    gap: var(--cascivo-space-3);
    inline-size: 100%;
    box-sizing: border-box;
    font-family: var(--cascivo-font-sans);
    color: var(--cascivo-color-text);
    border-radius: var(--cascivo-radius-item);
    /* `asChild` can render this styling onto a real <a>. */
    text-decoration: none;

    &[data-size='sm'] {
      padding-inline: var(--cascivo-space-3);
      padding-block: var(--cascivo-space-2);
      font-size: var(--cascivo-text-xs);
    }

    &[data-size='md'] {
      padding-inline: var(--cascivo-space-4);
      padding-block: var(--cascivo-space-3);
      font-size: var(--cascivo-text-sm);
    }

    &[data-variant='muted'] {
      background-color: var(--cascivo-color-bg-subtle);
    }
  }

  .media {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: none;
    color: var(--cascivo-color-text-subtle);
  }

  .content {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-1);
    min-inline-size: 0;
  }

  .title {
    font-weight: var(--cascivo-font-medium);
    line-height: var(--cascivo-leading-tight);
    color: var(--cascivo-color-text);
  }

  .description {
    margin: 0;
    font-size: var(--cascivo-text-xs);
    color: var(--cascivo-color-text-subtle);
    line-height: var(--cascivo-leading-normal);
  }

  .actions {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-2);
    flex: none;
  }
}

